// Persistent journey facts only. Renderers and temporary ability histories never enter saves.
export const PROLOGUE_START={x:-145,y:33,z:131};
export const SKY_START={x:-145,y:76,z:78};
export const SKY_EXIT={x:-145,y:84,z:3};
export const SKY_PARTS=[{id:'sky-forest-panel',kind:'panel',x:-151,y:76.3,z:90,rot:Math.PI/2,socket:null},{id:'sky-panel',kind:'panel',x:-152,y:76.3,z:73,rot:0,socket:null},{id:'sky-courier',kind:'counterweight',x:-151,y:105.45,z:114,rot:0,socket:null,driveStopped:false}];
export function journeyState(legacy=true){return {stage:legacy?'hub':'prologue',scene:'trial',mural:false,weave:legacy,bind:legacy,rise:legacy,echo:legacy,echoUsed:false,fabric:legacy,glider:legacy,map:legacy};}
export function beginJourney(state){state.journey=journeyState(false);state.journey.stage='sky';state.journey.scene='overworld';state.equipment={weapon:'mechanic-blade',modifier:null};Object.assign(state.player,{x:-1510,y:260,z:1190});state.safe={x:-1510,y:260,z:1190};state.objects.push(...SKY_PARTS.map(p=>({...p})));return state;}
export function validateJourney(j){if(j&&j.scene===undefined)j.scene='trial';if(!j||!['trial','overworld','weave','bind','rise','echo'].includes(j.scene)||!['prologue','sky','descent','hub'].includes(j.stage)||!['mural','weave','bind','rise','echo','echoUsed','fabric','glider','map'].every(k=>typeof j[k]==='boolean'))throw Error('Invalid expedition chapter data.');if(j.stage==='descent'&&!skyComplete(j))throw Error('Incomplete sky exit.');return j;}
export function skyComplete(j){return ['weave','bind','rise','echo'].every(k=>j[k]);}
export function bindEquipment(state){if(state.equipment.modifier==='prism')return {ok:false,message:'The blade already carries a prism.'};if(state.inventory.glass<1)return {ok:false,message:'One mossglass is required. The sky workbench has a recovery supply.'};state.inventory.glass--;state.equipment.modifier='prism';return {ok:true,message:'Prism-bound blade · +1 damage · breaks resonant seals'};}
export function grantGlider(state){if(state.journey.glider||!state.journey.fabric)return false;state.journey.glider=true;state.journey.map=true;return true;}
export function journeyObjective(state){const j=state.journey;if(!j)return null;if(j.stage==='prologue')return j.mural?'Follow Eda to the bound engine at the north end.':'Follow Eda. Examine the western mural.';if(j.stage==='sky'){if(j.scene==='overworld')return 'Explore the archipelago. Enter the four marked shrines; return to the northern temple after collecting their seals.';if(!j.weave)return 'Threadbind the loose panel into the bridge bracket.';if(!j.bind)return 'Find the prism workbench in the southwest forest. Bind the blade, then strike the northern seal.';if(!j.rise)return 'Reach the eastern snowy island. Rise through the shrine’s marked ceiling.';if(!j.echo)return 'Reach the high southern island: Rise through the two ceilings near (-145,117). Reset its courier, Echo it back and cancel on the plate.';return 'Four trials complete. Activate each completed shrine’s seal, then reach the Temple of Time in the north.';}if(j.stage==='descent')return 'Ride the wind cradle to the surface camp. Move to steer; interact to finish the descent.';if(!j.glider)return j.fabric?'Return the weathercloth to Sella for your glider.':'Speak with Sella and retrieve the weathercloth west of camp.';return null;}
